"""NEBIM KEŞİF 41 — LEFKOŞA (S01) 12.08.2026 SAYIMI NEBİM'E İŞLENDİ Mİ? (salt-okunur)

Mağaza sayımı 12.08.2026 kapanışından sonra yapıldı (3.837 barkod / 8.018 adet;
bu dosyaya gömülü). Nebim'e 25.08.2026'da "12.08 kapanış stoku budur" diye
işlendiği söyleniyor; 12.08'den sonraki satışlar stoktan düşmeye devam ediyor.
Şüphe: sayımda VAR denen bazı ürünler, satışı olmadığı hâlde stokta 0 görünüyor.

Mantık (her ürün için, depo S01):
  Stok12      = 12.08 kapanışına kadarki tüm hareketlerin bakiyesi (belge tarihi ≤ 12.08)
  Düzeltme    = 13.08'den sonra GİRİLEN toplu düzeltme/sayım hareketleri (tip otomatik tespit)
  Satış/İade  = 13.08'den sonraki perakende satış ve iadeler (trInvoice, S01, ProcessCode R)
  Diğer       = 13.08'den sonraki transfer vb. hareketler
  StokŞimdi   = bugünkü bakiye
  FARK        = (Stok12 + Düzeltme sonraki) − Sayım   → 0 ise sayım doğru işlenmiş
                (aynı şey: StokŞimdi − (Sayım + satış/iade/diğer))

Bölümler:
  A) Şema: trStock kolonları, depo kodları, adında sayım/count geçen tablolar, tip açıklamaları
  B) S01 Ağustos–Eylül hareket profili (tip × belge tarihi × giriş tarihi) → 25.08 toplu girişi
  C) Barkod → ürün kimliği (prItemBarcode), eşleşmeyenler
  D) Ürün bazında mutabakat + özet + şüpheli listeler
  E) Ters kontrol: sayımda OLMAYAN ama Nebim'de S01 stoğu görünen ürünler
  F) Şüpheli ürünlerin son hareketleri ve diğer depolardaki stoğu
  G) CSV: KESIF41-SONUC.csv (sayım satırları), KESIF41-TERS.csv (sayımda olmayanlar)
Çıktı: KESIF41-CIKTI.txt   (hiçbir şey YAZMAZ, sadece SELECT)
"""
