OUT = []


def log(*a):
    s = " ".join(str(x) for x in a)
    print(s)
    OUT.append(s)


def bolum(baslik):
    def dekore(fn):
        def sarili(*a, **k):
            log(f"\n===== {baslik} =====")
            try:
                return fn(*a, **k)
            except Exception:
                log("BÖLÜM HATASI:\n" + traceback.format_exc())
        return sarili
    return dekore


def kolonlar(cur, tablo):
    cur.execute("SELECT COLUMN_NAME, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS "
                "WHERE TABLE_NAME = ? ORDER BY ORDINAL_POSITION", tablo)
    return [(r[0], r[1]) for r in cur.fetchall()]


def tablo_var(cur, tablo):
    cur.execute("SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = ?", tablo)
    return cur.fetchone()[0] > 0


def f(x):
    if x is None:
        return 0.0
    if isinstance(x, Decimal):
        return float(x)
    try:
        return float(x)
    except Exception:
        return 0.0


def s(x):
    return "" if x is None else str(x).strip()


def d(x):
    """datetime/date/str -> date"""
    if x is None:
        return None
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x
    try:
        return datetime.strptime(str(x)[:10], "%Y-%m-%d").date()
    except Exception:
        return None


def qi(x):
    v = f(x)
    return int(v) if abs(v - int(v)) < 1e-9 else v


def chunks(lst, n=900):
    for i in range(0, len(lst), n):
        yield lst[i:i + n]


# ---------------------------------------------------------------- durum
class Sema:
    st_cols = []
    st_date = None          # trStock belge tarihi kolonu
    st_created = None       # trStock oluşturma tarihi kolonu
    tip_cols = []           # trStock tip kolonları (TransTypeCode / ProcessCode / InnerProcessCode …)
    dim2 = False            # ItemDim2Code hem trStock hem prItemBarcode'da var mı
    docno = None            # trStock belge no kolonu
    tip_aciklama = {}       # (kolon, kod) -> açıklama


SEMA = Sema()
KAYIT = {}          # barkod -> dict
KEY2BARKOD = {}     # ürün anahtarı -> barkod
ACILIS = {}         # key -> bakiye (belge tarihi < PENCERE_BAS)
HAREKET = defaultdict(list)   # key -> [(tip_tuple, belge_tarihi, giris_tarihi, in, out, rows)]
SATIS = defaultdict(lambda: [0.0, 0.0])   # key -> [satış adedi, iade adedi] (≥ SONRASI)
ADJ_TIPLER = set()  # düzeltme sayılan tip tuple'ları


def key_of(row_item, row_color, row_dim1, row_dim2=None):
    k = (s(row_item), s(row_color), s(row_dim1))
    if SEMA.dim2:
        k = k + (s(row_dim2),)
    return k


def key_cols(alias):
    cols = [f"{alias}.ItemCode", f"{alias}.ColorCode", f"{alias}.ItemDim1Code"]
    if SEMA.dim2:
        cols.append(f"{alias}.ItemDim2Code")
    return cols


def tip_str(t):
    parts = []
    for c, v in zip(SEMA.tip_cols, t):
        ac = SEMA.tip_aciklama.get((c, s(v)))
        parts.append(f"{c}={s(v)}" + (f"({ac})" if ac else ""))
    return " ".join(parts) if parts else "(tip yok)"


# ---------------------------------------------------------------- A
@bolum("A) ŞEMA")
def a_sema(cur):
    SEMA.st_cols = kolonlar(cur, "trStock")
    names = [c for c, _ in SEMA.st_cols]
    log("  trStock kolonları: " + ", ".join(names))
    date_cols = [c for c, t in SEMA.st_cols if t in ("date", "datetime", "datetime2", "smalldatetime")]
    log("  tarih tipli kolonlar: " + ", ".join(date_cols))
    for cand in ("DocumentDate", "TransDate", "StockDate", "OperationDate", "InvoiceDate",
                 "ShipmentDate", "Date", "DocDate"):
        if cand in names:
            SEMA.st_date = cand
            break
    if not SEMA.st_date:
        rest = [c for c in date_cols if "Created" not in c and "Updated" not in c]
        SEMA.st_date = rest[0] if rest else ("CreatedDate" if "CreatedDate" in names else None)
    SEMA.st_created = "CreatedDate" if "CreatedDate" in names else SEMA.st_date
    SEMA.tip_cols = [c for c in ("TransTypeCode", "ProcessCode", "InnerProcessCode",
                                 "StockTransTypeCode") if c in names]
    SEMA.docno = next((c for c in ("DocumentNumber", "InvoiceNumber", "ShipmentNumber",
                                   "InnerNumber", "RefNumber") if c in names), None)
    log(f"  → belge tarihi kolonu: {SEMA.st_date} | giriş tarihi: {SEMA.st_created} | "
        f"tip kolonları: {SEMA.tip_cols} | belge no: {SEMA.docno}")
    if not SEMA.st_date:
        raise RuntimeError("trStock'ta tarih kolonu bulunamadı")

    bk = [c for c, _ in kolonlar(cur, "prItemBarcode")]
    SEMA.dim2 = ("ItemDim2Code" in names) and ("ItemDim2Code" in bk)
    log(f"  prItemBarcode kolonları: {', '.join(bk)}  | ItemDim2Code anahtara dahil: {SEMA.dim2}")

    # depo kodları
    cur.execute(f"""
        SELECT TOP 25 WarehouseCode, COUNT(*), MIN({SEMA.st_date}), MAX({SEMA.st_date})
        FROM trStock WITH(NOLOCK) GROUP BY WarehouseCode ORDER BY COUNT(*) DESC""")
    log("  trStock depo dağılımı (depo | satır | ilk | son):")
    for r in cur.fetchall():
        log(f"   {s(r[0]):8} | {r[1]:>8} | {s(r[2])[:10]} | {s(r[3])[:10]}")
    if tablo_var(cur, "cdWarehouseDesc"):
        try:
            cur.execute("SELECT WarehouseCode, WarehouseDescription FROM cdWarehouseDesc "
                        "WITH(NOLOCK) WHERE LangCode='TR'")
            log("  depo açıklamaları: " + "; ".join(f"{s(r[0])}={s(r[1])}" for r in cur.fetchall()))
        except Exception as e:
            log(f"  (cdWarehouseDesc okunamadı: {e})")

    # sayım tabloları
    cur.execute("""
        SELECT TABLE_NAME, TABLE_TYPE FROM INFORMATION_SCHEMA.TABLES
        WHERE (TABLE_NAME LIKE '%Count%' OR TABLE_NAME LIKE '%Inventory%'
           OR TABLE_NAME LIKE '%Sayim%' OR TABLE_NAME LIKE '%Physical%'
           OR TABLE_NAME LIKE '%StockTak%' OR TABLE_NAME LIKE '%Adjust%'
        )
          AND TABLE_NAME NOT LIKE '%Account%' AND TABLE_NAME NOT LIKE '%Discount%'
          AND TABLE_NAME NOT LIKE '%Country%' AND TABLE_NAME NOT LIKE '%Counter%'
        ORDER BY TABLE_TYPE, TABLE_NAME""")
    rows = cur.fetchall()
    log(f"  adında Count/Inventory/Sayim/Physical/Adjust geçen tablo/görünüm: {len(rows)}")
    for tn, tt in rows[:60]:
        if tt != "BASE TABLE":
            log(f"   {tt[:5]} {tn}")
            continue
        try:
            cur.execute(f"SELECT COUNT(*) FROM [{tn}] WITH(NOLOCK)")
            n = cur.fetchone()[0]
            ek = ""
            if n:
                kc = kolonlar(cur, tn)
                dc = [c for c, t in kc if t in ("date", "datetime", "datetime2")]
                if dc:
                    cur.execute(f"SELECT MIN([{dc[0]}]), MAX([{dc[0]}]) FROM [{tn}] WITH(NOLOCK)")
                    mn, mx = cur.fetchone()
                    ek = f" {dc[0]}: {s(mn)[:10]} → {s(mx)[:10]}"
                    if "WarehouseCode" in [c for c, _ in kc]:
                        cur.execute(f"SELECT WarehouseCode, COUNT(*), MAX([{dc[0]}]) FROM [{tn}] "
                                    f"WITH(NOLOCK) GROUP BY WarehouseCode")
                        ek += " | depo: " + "; ".join(f"{s(r[0])}:{r[1]} (son {s(r[2])[:10]})"
                                                      for r in cur.fetchall())
            log(f"   TABLE {tn}: {n} satır{ek}")
        except Exception as e:
            log(f"   TABLE {tn}: okunamadı ({str(e)[:80]})")

    # tip açıklamaları
    for col, tbl, codecol, desccol in (
            ("TransTypeCode", "bsTransTypeDesc", "TransTypeCode", "TransTypeDescription"),
            ("ProcessCode", "bsProcessDesc", "ProcessCode", "ProcessDescription"),
            ("InnerProcessCode", "bsInnerProcessDesc", "InnerProcessCode", "InnerProcessDescription"),
            ("StockTransTypeCode", "bsStockTransTypeDesc", "StockTransTypeCode", "StockTransTypeDescription")):
        if col not in SEMA.tip_cols or not tablo_var(cur, tbl):
            continue
        try:
            cur.execute(f"SELECT {codecol}, {desccol} FROM {tbl} WITH(NOLOCK) WHERE LangCode='TR'")
            for r in cur.fetchall():
                SEMA.tip_aciklama[(col, s(r[0]))] = s(r[1])
            log(f"  {tbl}: {sum(1 for k in SEMA.tip_aciklama if k[0] == col)} açıklama")
        except Exception as e:
            log(f"  ({tbl} okunamadı: {str(e)[:80]})")


# ---------------------------------------------------------------- B
@bolum("B) S01 AĞUSTOS–EYLÜL HAREKET PROFİLİ (toplu giriş günü tespiti)")
def b_profil(cur):
    tip_sel = ", ".join(SEMA.tip_cols)
    tip_sel = (tip_sel + ", ") if tip_sel else ""
    cur.execute(f"""
        SELECT {tip_sel}CAST({SEMA.st_date} AS date) AS BelgeT, CAST({SEMA.st_created} AS date) AS GirisT,
               COUNT(*), SUM(ISNULL(In_Qty1,0)), SUM(ISNULL(Out_Qty1,0)),
               COUNT(DISTINCT ItemCode + '|' + ColorCode + '|' + ItemDim1Code)
        FROM trStock WITH(NOLOCK)
        WHERE WarehouseCode = ? AND {SEMA.st_date} >= ?
        GROUP BY {tip_sel}CAST({SEMA.st_date} AS date), CAST({SEMA.st_created} AS date)
        ORDER BY GirisT, BelgeT""", (WH, PENCERE_BAS))
    nt = len(SEMA.tip_cols)
    rows = cur.fetchall()
    log(f"  gruplar: {len(rows)} (tip × belge tarihi × giriş tarihi)")
    log("  giriş T   | belge T    | satır | giriş adet | çıkış adet | ürün | tip")
    # tip bazında toplam (sayım sonrası)
    tip_toplam = defaultdict(lambda: [0, 0.0, 0.0, defaultdict(int)])   # rows, in, out, {girisT: rows}
    geri_tarihli = []
    for r in rows:
        t = tuple(s(x) for x in r[:nt])
        belge, giris, n, qin, qout, nitem = d(r[nt]), d(r[nt + 1]), r[nt + 2], f(r[nt + 3]), f(r[nt + 4]), r[nt + 5]
        if n >= 30 or qin + qout >= 100:
            log(f"  {s(giris):10} | {s(belge):10} | {n:>5} | {qin:>10.0f} | {qout:>10.0f} | {nitem:>4} | {tip_str(t)}")
        if giris and giris >= SONRASI:
            tt = tip_toplam[t]
            tt[0] += n; tt[1] += qin; tt[2] += qout; tt[3][giris] += n
        if belge and giris and belge <= SAYIM_TARIHI and giris >= SONRASI:
            geri_tarihli.append((t, belge, giris, n, qin, qout))
    log("\n  13.08'den sonra GİRİLEN hareketler, tip bazında (satır | giriş | çıkış | en yoğun gün → satır):")
    for t, (n, qin, qout, gunler) in sorted(tip_toplam.items(), key=lambda kv: -kv[1][0]):
        gun, gn = max(gunler.items(), key=lambda kv: kv[1])
        oran = gn / n if n else 0
        log(f"   {n:>6} | {qin:>8.0f} | {qout:>8.0f} | {s(gun)} → {gn} (%{oran*100:.0f}) | {len(gunler)} gün | {tip_str(t)}")
    log("\n  GERİ TARİHLİ girişler (belge tarihi ≤ 12.08 ama 13.08+ girilmiş):")
    if not geri_tarihli:
        log("   yok")
    for t, belge, giris, n, qin, qout in geri_tarihli:
        log(f"   belge {belge} giriş {giris} | {n} satır | +{qin:.0f} −{qout:.0f} | {tip_str(t)}")
    log(f"\n  {ISLEME_TARIHI} günü girilen hareketler (tip bazında):")
    bul = False
    for r in rows:
        t = tuple(s(x) for x in r[:nt])
        if d(r[nt + 1]) == ISLEME_TARIHI:
            bul = True
            log(f"   belge {s(d(r[nt]))} | {r[nt + 2]} satır | +{f(r[nt + 3]):.0f} −{f(r[nt + 4]):.0f} | {tip_str(t)}")
    if not bul:
        log("   o gün S01'e hiç hareket girilmemiş")

    # düzeltme tipi tespiti
    #  1) tip açıklamasında sayım/düzeltme/fark geçenler (bsProcessDesc vb.)
    #  2) yoksa: satış (R) olmayan, ≥100 satırlı, ≥%60'ı tek güne yığılmış tipler (toplu giriş)
    pc_idx = SEMA.tip_cols.index("ProcessCode") if "ProcessCode" in SEMA.tip_cols else None
    anahtar = ("sayım", "sayim", "count", "düzelt", "duzelt", "adjust", "fark", "envanter", "inventory")
    aciklamali = set()
    toplu = set()
    for t, (n, qin, qout, gunler) in tip_toplam.items():
        if pc_idx is not None and t[pc_idx] == "R":
            continue
        metin = tip_str(t).lower()
        if any(a in metin for a in anahtar):
            aciklamali.add(t)
        gun, gn = max(gunler.items(), key=lambda kv: kv[1])
        if n >= 100 and gn / n >= 0.6:
            toplu.add(t)
    log("\n  düzeltme adayı tipler — açıklamasında sayım/düzeltme geçen: " +
        ("; ".join(tip_str(t) for t in aciklamali) or "YOK"))
    log("  düzeltme adayı tipler — toplu giriş (≥100 satır, ≥%60 tek gün, satış değil): " +
        ("; ".join(tip_str(t) for t in toplu) or "YOK"))
    ADJ_TIPLER.update(aciklamali if aciklamali else toplu)
    if ADJ_TIPLER:
        log("  → DÜZELTME/SAYIM KAYDI SAYILAN TİPLER (" + ("açıklamaya göre" if aciklamali else "toplu girişe göre") + "):")
        for t in ADJ_TIPLER:
            log("     " + tip_str(t))
    else:
        log("  → Düzeltme/sayım kaydına benzeyen tip BULUNAMADI (13.08+ girişlerde). "
            "Bu durumda FARK = 12.08 stoğu − sayım (ham sayım farkı) olarak okunmalı.")
    return rows


# ---------------------------------------------------------------- C
@bolum("C) BARKOD → ÜRÜN KİMLİĞİ")
def c_kimlik(cur):
    for bk, adet, model, renk, beden in SAYIM:
        KAYIT[bk] = {"Barkod": bk, "Sayim": adet, "Model": model, "RenkKodu": renk, "Beden": beden}
    dim2 = ", b.ItemDim2Code" if SEMA.dim2 else ", NULL"
    eslesmeyen = []
    coklu = 0
    for parca in chunks(SAYIM, 900):
        vals = ",".join(f"(N'{bk}')" for bk, *_ in parca)
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {vals}) v(Barcode))
            SELECT S.Barcode, b.ItemCode, b.ColorCode, b.ItemDim1Code{dim2}, b.ItemTypeCode,
                   (SELECT COUNT(*) FROM prItemBarcode bb2 WITH(NOLOCK) WHERE bb2.Barcode = S.Barcode)
            FROM S
            OUTER APPLY (SELECT TOP 1 * FROM prItemBarcode bb WITH(NOLOCK)
                         WHERE bb.Barcode = S.Barcode ORDER BY bb.ItemCode) b""")
        for r in cur.fetchall():
            bk = s(r[0])
            if r[1] is None:
                eslesmeyen.append(bk)
                continue
            k = key_of(r[1], r[2], r[3], r[4])
            KAYIT[bk].update({"ItemCode": k[0], "ColorCode": k[1], "Dim1": k[2],
                              "Dim2": (k[3] if SEMA.dim2 else ""), "ItemType": s(r[5]), "Key": k})
            if (r[6] or 0) > 1:
                coklu += 1
            if k in KEY2BARKOD and KEY2BARKOD[k] != bk:
                KAYIT[bk]["Not"] = f"aynı ürün başka barkodla da sayılmış: {KEY2BARKOD[k]}"
            KEY2BARKOD.setdefault(k, bk)
    n = sum(1 for v in KAYIT.values() if v.get("Key"))
    log(f"  eşleşen: {n} / {len(KAYIT)} | birden çok prItemBarcode satırı olan: {coklu}")
    if eslesmeyen:
        log(f"  EŞLEŞMEYEN {len(eslesmeyen)} barkod: " + ", ".join(eslesmeyen[:100]))
    else:
        log("  eşleşmeyen barkod yok ✓")
    # model kodu kontrolü: Excel'deki model kodu ≠ Nebim ItemCode olanlar
    farkli = [v for v in KAYIT.values() if v.get("Key") and v["Model"] != v["ItemCode"]]
    log(f"  Excel model kodu ≠ Nebim ItemCode olan satır: {len(farkli)}" +
        (" (örn: " + "; ".join(f"{v['Barkod']} {v['Model']}→{v['ItemCode']}" for v in farkli[:8]) + ")" if farkli else ""))


# ---------------------------------------------------------------- D (veri çekme)
def hareketleri_cek(cur):
    kc = ", ".join(key_cols("st"))
    # açılış bakiyesi (pencere öncesi)
    cur.execute(f"""
        SELECT {kc}, SUM(ISNULL(st.In_Qty1,0)) - SUM(ISNULL(st.Out_Qty1,0))
        FROM trStock st WITH(NOLOCK)
        WHERE st.WarehouseCode = ? AND st.{SEMA.st_date} < ?
        GROUP BY {kc}""", (WH, PENCERE_BAS))
    nk = 4 if SEMA.dim2 else 3
    for r in cur.fetchall():
        ACILIS[key_of(*r[:nk])] = f(r[nk])
    log(f"  açılış bakiyesi ({PENCERE_BAS} öncesi) olan ürün: {len(ACILIS)}; "
        f"toplam {sum(ACILIS.values()):.0f} adet; sıfır olmayan: {sum(1 for v in ACILIS.values() if abs(v) > 1e-9)}")

    # pencere hareketleri
    tip_sel = ", ".join(f"st.{c}" for c in SEMA.tip_cols)
    tip_sel = (tip_sel + ", ") if tip_sel else ""
    cur.execute(f"""
        SELECT {kc}, {tip_sel}CAST(st.{SEMA.st_date} AS date), CAST(st.{SEMA.st_created} AS date),
               SUM(ISNULL(st.In_Qty1,0)), SUM(ISNULL(st.Out_Qty1,0)), COUNT(*)
        FROM trStock st WITH(NOLOCK)
        WHERE st.WarehouseCode = ? AND st.{SEMA.st_date} >= ?
        GROUP BY {kc}, {tip_sel}CAST(st.{SEMA.st_date} AS date), CAST(st.{SEMA.st_created} AS date)""",
                (WH, PENCERE_BAS))
    nt = len(SEMA.tip_cols)
    n = 0
    for r in cur.fetchall():
        k = key_of(*r[:nk])
        t = tuple(s(x) for x in r[nk:nk + nt])
        HAREKET[k].append((t, d(r[nk + nt]), d(r[nk + nt + 1]), f(r[nk + nt + 2]), f(r[nk + nt + 3]), r[nk + nt + 4]))
        n += 1
    log(f"  pencere ({PENCERE_BAS}+) hareket grubu: {n}; ürün: {len(HAREKET)}")

    # perakende satış/iade (fatura tablosu, mağaza S01)
    lk = ", ".join(key_cols("l"))
    cur.execute(f"""
        SELECT {lk}, h.IsReturn, SUM(l.Qty1), COUNT(*)
        FROM trInvoiceLine l WITH(NOLOCK)
        JOIN trInvoiceHeader h WITH(NOLOCK) ON h.InvoiceHeaderID = l.InvoiceHeaderID
        WHERE h.ProcessCode = 'R' AND h.StoreCode = ? AND h.InvoiceDate >= ?
        GROUP BY {lk}, h.IsReturn""", (STORE, SONRASI))
    ns = ni = 0.0
    for r in cur.fetchall():
        k = key_of(*r[:nk])
        if r[nk]:
            SATIS[k][1] += f(r[nk + 1]); ni += f(r[nk + 1])
        else:
            SATIS[k][0] += f(r[nk + 1]); ns += f(r[nk + 1])
    log(f"  {SONRASI}+ perakende: satış {ns:.0f} adet, iade {ni:.0f} adet, ürün {len(SATIS)}")


def hesapla(k, sayim):
    """Bir ürün için mutabakat sözlüğü."""
    acilis = ACILIS.get(k, 0.0)
    stok12 = acilis
    stok_simdi = acilis
    duz_sonra = 0.0       # düzeltme tipleri, belge tarihi ≥ 13.08
    duz_giris = 0.0       # düzeltme tipleri, GİRİŞ tarihi ≥ 13.08 (geri tarihli dahil) — bilgi
    diger_sonra = 0.0     # düzeltme dışı, belge ≥ 13.08 (satış/iade/transfer …)
    tip_sonra = defaultdict(float)
    son_hareket = None
    for t, belge, giris, qin, qout, n in HAREKET.get(k, []):
        net = qin - qout
        stok_simdi += net
        if belge is None or belge <= SAYIM_TARIHI:
            stok12 += net
        else:
            if t in ADJ_TIPLER:
                duz_sonra += net
            else:
                diger_sonra += net
            tip_sonra[t] += net
        if t in ADJ_TIPLER and giris and giris >= SONRASI:
            duz_giris += net
        if belge and (son_hareket is None or belge > son_hareket[0]):
            son_hareket = (belge, t, net)
    satis, iade = SATIS.get(k, [0.0, 0.0])
    stok12_duz = stok12 + duz_sonra
    fark = stok12_duz - sayim
    return {"Acilis": acilis, "Stok12": stok12, "DuzeltmeSonra": duz_sonra, "DuzeltmeGiris": duz_giris,
            "Stok12Duz": stok12_duz, "SatisSonra": satis, "IadeSonra": iade, "DigerSonra": diger_sonra,
            "StokSimdi": stok_simdi, "Fark": fark, "TipSonra": dict(tip_sonra), "SonHareket": son_hareket}


@bolum("D) ÜRÜN BAZINDA MUTABAKAT")
def d_mutabakat(cur):
    hareketleri_cek(cur)
    for v in KAYIT.values():
        k = v.get("Key")
        if not k:
            continue
        v.update(hesapla(k, v["Sayim"]))
    yok_ilk_hareket = 0
    for v in KAYIT.values():
        if v.get("Key") and v["Key"] not in ACILIS and v["Key"] not in HAREKET:
            v["Durum"] = "S01'DE HİÇ HAREKET YOK"
            yok_ilk_hareket += 1
    dogru = [v for v in KAYIT.values() if v.get("Key") and abs(v["Fark"]) < 1e-9]
    eksik = [v for v in KAYIT.values() if v.get("Key") and v["Fark"] < -1e-9]
    fazla = [v for v in KAYIT.values() if v.get("Key") and v["Fark"] > 1e-9]
    for v in dogru:
        v.setdefault("Durum", "DOĞRU")
    for v in eksik:
        v["Durum"] = v.get("Durum") or ("STOK EKSİK (satış yok)" if v["SatisSonra"] == 0 else "STOK EKSİK")
    for v in fazla:
        v["Durum"] = v.get("Durum") or "STOK FAZLA"
    toplam = sum(v["Sayim"] for v in KAYIT.values() if v.get("Key"))
    log(f"  sayım satırı: {len(KAYIT)} | Nebim'de bulunan: {len(dogru)+len(eksik)+len(fazla)} | sayım adedi: {toplam}")
    log(f"  düzeltme tipi olarak alınan: {[tip_str(t) for t in ADJ_TIPLER] or 'YOK'}")
    log(f"\n  SONUÇ  (FARK = 12.08 stoğu + düzeltme − sayım):")
    log(f"   ✓ FARK = 0 (sayım doğru işlenmiş)        : {len(dogru):>5} satır / {sum(v['Sayim'] for v in dogru):>6} adet")
    log(f"   ✗ FARK < 0 (Nebim stoğu sayımdan EKSİK)  : {len(eksik):>5} satır / eksik {-sum(v['Fark'] for v in eksik):>6.0f} adet")
    log(f"       bunlardan 13.08+ satışı hiç olmayan  : {sum(1 for v in eksik if v['SatisSonra']==0):>5} satır")
    log(f"       bunlardan Nebim stoğu şu an 0/negatif: {sum(1 for v in eksik if v['StokSimdi']<=0):>5} satır")
    log(f"       bunlardan S01'de hiç hareketi olmayan: {yok_ilk_hareket:>5} satır")
    log(f"   ✗ FARK > 0 (Nebim stoğu sayımdan FAZLA)  : {len(fazla):>5} satır / fazla {sum(v['Fark'] for v in fazla):>6.0f} adet")
    # ham 12.08 karşılaştırması (düzeltme hariç) — sayım öncesi Nebim ne diyordu
    ham_esit = sum(1 for v in KAYIT.values() if v.get("Key") and abs(v["Stok12"] - v["Sayim"]) < 1e-9)
    log(f"\n  bilgi: düzeltme HARİÇ 12.08 stoğu sayımla aynı olan satır: {ham_esit} / {len(KAYIT)}")
    log(f"  bilgi: düzeltme kaydı (13.08+ girilen) dokunan sayım ürünü: "
        f"{sum(1 for v in KAYIT.values() if v.get('Key') and abs(v['DuzeltmeGiris'])>1e-9)}; "
        f"net düzeltme adedi: {sum(v['DuzeltmeGiris'] for v in KAYIT.values() if v.get('Key')):.0f}")
    log(f"  bilgi: sayım ürünlerinin bugünkü S01 stoğu toplamı: "
        f"{sum(v['StokSimdi'] for v in KAYIT.values() if v.get('Key')):.0f} adet; "
        f"13.08+ satış {sum(v['SatisSonra'] for v in KAYIT.values() if v.get('Key')):.0f}, "
        f"iade {sum(v['IadeSonra'] for v in KAYIT.values() if v.get('Key')):.0f}")

    def satir(v):
        sh = v.get("SonHareket")
        shs = f"{sh[0]} {tip_str(sh[1])} {sh[2]:+.0f}" if sh else "-"
        return (f"   {v['Barkod']} {v['Model']:<13} {v['RenkKodu']:>3} {v['Beden']:>4} | sayım {v['Sayim']:>3} | "
                f"12.08 {v['Stok12']:>4.0f} düz {v['DuzeltmeSonra']:>+3.0f} | satış {v['SatisSonra']:>3.0f} iade {v['IadeSonra']:>2.0f} "
                f"diğer {v['DigerSonra']:>+3.0f} | şimdi {v['StokSimdi']:>4.0f} | FARK {v['Fark']:>+4.0f} | son: {shs}")

    log(f"\n  --- STOK EKSİK, 13.08+ SATIŞI OLMAYAN (ilk {LISTE_LIMIT}; kullanıcının şüphesi tam bu) ---")
    lst = sorted((v for v in eksik if v["SatisSonra"] == 0), key=lambda v: (v["Fark"], v["Barkod"]))
    for v in lst[:LISTE_LIMIT]:
        log(satir(v))
    log(f"  (toplam {len(lst)} satır)")
    log(f"\n  --- STOK EKSİK, satışı OLAN (ilk {LISTE_LIMIT//2}) ---")
    lst = sorted((v for v in eksik if v["SatisSonra"] > 0), key=lambda v: (v["Fark"], v["Barkod"]))
    for v in lst[:LISTE_LIMIT // 2]:
        log(satir(v))
    log(f"  (toplam {len(lst)} satır)")
    log(f"\n  --- STOK FAZLA (ilk {LISTE_LIMIT//2}) ---")
    lst = sorted(fazla, key=lambda v: (-v["Fark"], v["Barkod"]))
    for v in lst[:LISTE_LIMIT // 2]:
        log(satir(v))
    log(f"  (toplam {len(lst)} satır)")
    return eksik, fazla


# ---------------------------------------------------------------- E
TERS = []


@bolum("E) TERS KONTROL — sayımda OLMAYAN ama Nebim'de S01 stoğu olan ürünler")
def e_ters(cur):
    sayilan = set(v["Key"] for v in KAYIT.values() if v.get("Key"))
    tum = set(ACILIS) | set(HAREKET)
    for k in tum - sayilan:
        h = hesapla(k, 0)
        if abs(h["StokSimdi"]) < 1e-9 and abs(h["Stok12Duz"]) < 1e-9:
            continue
        h["Key"] = k
        TERS.append(h)
    poz = [h for h in TERS if h["Stok12Duz"] > 1e-9]
    neg = [h for h in TERS if h["Stok12Duz"] < -1e-9]
    simdi_poz = [h for h in TERS if h["StokSimdi"] > 1e-9]
    log(f"  sayımda olmayıp S01'de bakiyesi olan ürün: {len(TERS)}")
    log(f"   12.08 stoğu (+düzeltme) > 0 : {len(poz)} ürün / {sum(h['Stok12Duz'] for h in poz):.0f} adet  ← sayım doğru işlenseydi 0 olmalıydı")
    log(f"   12.08 stoğu (+düzeltme) < 0 : {len(neg)} ürün / {sum(h['Stok12Duz'] for h in neg):.0f} adet")
    log(f"   bugün stoğu > 0             : {len(simdi_poz)} ürün / {sum(h['StokSimdi'] for h in simdi_poz):.0f} adet")
    # açıklama + barkod
    hedef = sorted(poz, key=lambda h: -h["Stok12Duz"])[:LISTE_LIMIT]
    if hedef:
        acikla_ekle(cur, hedef)
    log(f"\n  --- 12.08 stoğu > 0 olanlar (ilk {LISTE_LIMIT}, adet sırasıyla) ---")
    for h in hedef:
        k = h["Key"]
        log(f"   {h.get('Barkod','-'):13} {k[0]:<13} {k[1]:>3} {k[2]:>4} | 12.08 {h['Stok12']:>4.0f} düz {h['DuzeltmeSonra']:>+3.0f} "
            f"= {h['Stok12Duz']:>4.0f} | satış {h['SatisSonra']:>3.0f} | şimdi {h['StokSimdi']:>4.0f} | {h.get('Aciklama','')[:40]}")



def acikla_ekle(cur, hedefler):
    """Ürün anahtarı listesine ItemDescription + barkod ekler (chunk'lı)."""
    nk = 4 if SEMA.dim2 else 3
    for parca in chunks(hedefler, 400):
        vals = []
        for h in parca:
            k = h["Key"]
            vals.append("(" + ",".join(f"N'{x}'" for x in k) + ")")
        cols = ["ItemCode", "ColorCode", "ItemDim1Code"] + (["ItemDim2Code"] if SEMA.dim2 else [])
        cond = " AND ".join(f"bb.{c} = S.{c}" for c in cols)
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, b.Barcode, dd.ItemDescription
            FROM S
            OUTER APPLY (SELECT TOP 1 Barcode FROM prItemBarcode bb WITH(NOLOCK) WHERE {cond}) b
            OUTER APPLY (SELECT TOP 1 ItemDescription FROM cdItemDesc dd WITH(NOLOCK)
                         WHERE dd.ItemCode = S.ItemCode AND dd.LangCode='TR') dd""")
        m = {key_of(*r[:nk]): (s(r[nk]), s(r[nk + 1])) for r in cur.fetchall()}
        for h in parca:
            bk, ac = m.get(h["Key"], ("", ""))
            h["Barkod"] = bk or "-"
            h["Aciklama"] = ac


# ---------------------------------------------------------------- F
@bolum("F) ŞÜPHELİ ÜRÜNLER — S01 son 3 hareket + diğer depolardaki stok")
def f_detay(cur, eksik):
    hedef = sorted(eksik, key=lambda v: (v["Fark"], v["Barkod"]))[:300]
    if not hedef:
        log("  şüpheli ürün yok"); return
    nk = 4 if SEMA.dim2 else 3
    cols = ["ItemCode", "ColorCode", "ItemDim1Code"] + (["ItemDim2Code"] if SEMA.dim2 else [])
    tip_sel = ", ".join(f"st.{c}" for c in SEMA.tip_cols)
    tip_sel = (tip_sel + ", ") if tip_sel else ""
    docno = f"st.{SEMA.docno}" if SEMA.docno else "NULL"
    for parca in chunks(hedef, 300):
        vals = ["(" + ",".join(f"N'{x}'" for x in v["Key"]) + ")" for v in parca]
        cond = " AND ".join(f"st.{c} = S.{c}" for c in cols)
        # diğer depolar
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, st.WarehouseCode,
                   SUM(ISNULL(st.In_Qty1,0)) - SUM(ISNULL(st.Out_Qty1,0))
            FROM S JOIN trStock st WITH(NOLOCK) ON {cond}
            GROUP BY {','.join('S.'+c for c in cols)}, st.WarehouseCode""")
        depo = defaultdict(list)
        for r in cur.fetchall():
            if abs(f(r[nk + 1])) > 1e-9:
                depo[key_of(*r[:nk])].append(f"{s(r[nk])}:{f(r[nk+1]):.0f}")
        # son 3 hareket
        cur.execute(f"""
            WITH S AS (SELECT * FROM (VALUES {','.join(vals)}) v({','.join(cols)}))
            SELECT {','.join('S.'+c for c in cols)}, x.BelgeT, x.GirisT, {', '.join('x.'+c for c in SEMA.tip_cols)}{',' if SEMA.tip_cols else ''}
                   x.DocNo, x.Qin, x.Qout
            FROM S
            OUTER APPLY (SELECT TOP 3 CAST(st.{SEMA.st_date} AS date) AS BelgeT, CAST(st.{SEMA.st_created} AS date) AS GirisT,
                         {tip_sel}{docno} AS DocNo, ISNULL(st.In_Qty1,0) AS Qin, ISNULL(st.Out_Qty1,0) AS Qout
                         FROM trStock st WITH(NOLOCK) WHERE st.WarehouseCode = '{WH}' AND {cond}
                         ORDER BY st.{SEMA.st_date} DESC, st.{SEMA.st_created} DESC) x""")
        nt = len(SEMA.tip_cols)
        son = defaultdict(list)
        for r in cur.fetchall():
            if r[nk] is None:
                continue
            t = tuple(s(x) for x in r[nk + 2:nk + 2 + nt])
            son[key_of(*r[:nk])].append(
                f"{s(d(r[nk]))}(giriş {s(d(r[nk+1]))}) {tip_str(t)} {s(r[nk+2+nt])} +{f(r[nk+3+nt]):.0f}-{f(r[nk+4+nt]):.0f}")
        for v in parca:
            v["DigerDepolar"] = " ".join(depo.get(v["Key"], [])) or "-"
            v["Son3"] = " || ".join(son.get(v["Key"], [])) or "S01'de hareket yok"
    log(f"  ilk {len(hedef)} şüpheli ürün (FARK en eksikten başlayarak):")
    for v in hedef:
        log(f"   {v['Barkod']} {v['Model']} {v['RenkKodu']} {v['Beden']} | sayım {v['Sayim']} şimdi {v['StokSimdi']:.0f} FARK {v['Fark']:+.0f} "
            f"| diğer depolar: {v['DigerDepolar']} | son: {v['Son3']}")


# ---------------------------------------------------------------- G
@bolum("G) CSV")
def g_csv():
    tipler = sorted(set(t for v in KAYIT.values() for t in v.get("TipSonra", {})) |
                    set(t for h in TERS for t in h.get("TipSonra", {})))
    tip_kolon = [("T:" + tip_str(t)).replace(";", ",") for t in tipler]
    kolon = ["Barkod", "Model", "RenkKodu", "Beden", "Sayim", "ItemCode", "ColorCode", "Dim1", "Dim2", "Durum",
             "Acilis", "Stok12", "DuzeltmeSonra", "DuzeltmeGiris", "Stok12Duz", "SatisSonra", "IadeSonra",
             "DigerSonra", "StokSimdi", "Fark", "SonHareket", "DigerDepolar", "Son3", "Not"] + tip_kolon

    def hucre(x):
        if x is None:
            return ""
        if isinstance(x, float):
            return f"{x:.4f}".rstrip("0").rstrip(".")
        if isinstance(x, tuple):
            return " ".join(str(y) for y in x)
        return str(x).replace(";", ",").replace("\n", " ")

    def rows_of(items, is_ters=False):
        out = [";".join(kolon)]
        for v in items:
            v = dict(v)
            if is_ters:
                k = v["Key"]
                v.update({"Model": k[0], "RenkKodu": k[1], "Beden": k[2], "Sayim": 0,
                          "ItemCode": k[0], "ColorCode": k[1], "Dim1": k[2],
                          "Dim2": (k[3] if SEMA.dim2 else ""), "Durum": "SAYIMDA YOK",
                          "Not": v.get("Aciklama", "")})
            sh = v.get("SonHareket")
            if sh:
                v["SonHareket"] = f"{sh[0]} {tip_str(sh[1])} {sh[2]:+.0f}"
            ts = v.get("TipSonra", {})
            for t, kc in zip(tipler, tip_kolon):
                v[kc] = ts.get(t)
            out.append(";".join(hucre(v.get(c)) for c in kolon))
        return out

    for ad, satirlar in (("KESIF41-SONUC.csv", rows_of(sorted(KAYIT.values(), key=lambda v: v["Barkod"]))),
                         ("KESIF41-TERS.csv", rows_of(sorted(TERS, key=lambda h: -h["Stok12Duz"]), True))):
        try:
            with open(ad, "w", encoding="utf-8-sig") as fh:
                fh.write("\n".join(satirlar))
            log(f"  {ad} yazıldı ({len(satirlar)-1} satır).")
        except Exception as e:
            log(f"  {ad} yazılamadı: {e}")


def main():
    from satis_kopru import load_config, connect
    cfg = load_config()
    log(">>> KEŞİF 41 — Lefkoşa (S01) 12.08.2026 sayımı Nebim'e işlendi mi? (salt-okunur)")
    log(f"    sayım satırı {len(SAYIM)} / {sum(x[1] for x in SAYIM)} adet · depo {WH} · "
        f"sayım {SAYIM_TARIHI} · işleme {ISLEME_TARIHI} · çalıştırma {datetime.now():%Y-%m-%d %H:%M}")
    conn = connect(cfg)
    cur = conn.cursor()
    calistir(cur)


def calistir(cur):
    a_sema(cur)
    b_profil(cur)
    c_kimlik(cur)
    res = d_mutabakat(cur)
    eksik = res[0] if res else []
    e_ters(cur)
    f_detay(cur, eksik)
    g_csv()
    log("\n>>> KEŞİF 41 TAMAM. KESIF41-CIKTI.txt + KESIF41-SONUC.csv + KESIF41-TERS.csv dosyalarını AnyDesk ile Mac'e gönder.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        log(traceback.format_exc())
    try:
        with open("KESIF41-CIKTI.txt", "w", encoding="utf-8") as fh:
            fh.write("\n".join(OUT))
        print("\n>>> KESIF41-CIKTI.txt yazildi. <<<")
    except Exception as e:
        print("yazilamadi:", e)
